var EyvaUtils = Class.create();
EyvaUtils.prototype = {
    initialize: function() {
		this.PROFICIENT = {label: 'proficient', id: '258bfeb747bfa1102dabcd9bd36d438b'};
		this.NEEDSTRAINING = {label: 'needsTraining', id: '55eb7e7347bfa1102dabcd9bd36d43e2'};
		this.NEEDSHELP = {label: 'needsHelp', id: 'b5fb7aff477fa1102dabcd9bd36d4350'};
		this.UNQUALIFIED = {label: '', id: '3ffbfeb747bfa1102dabcd9bd36d438e'};
		this.MASTERIES = [this.PROFICIENT, this.NEEDSTRAINING, this.NEEDSHELP, this.UNQUALIFIED];
		this.SKILLS = [{
			name: 'Lot',
			getMasteryByWorker: (worker) => {
				// All kids have this skill
				return worker.getValue('adult') == false ? this.PROFICIENT.label : this.UNQUALIFIED.label;
			},
			getPositions: function() {
				// ===== TODO: Use position skills =====
				var positions = [];
				var positionGr = new GlideRecord('x_802331_eyva_position');
				positionGr.addQuery('normally_for_kids', true);
				positionGr.query();
				while (positionGr.next()) {
					positions.push({
						name: positionGr.name.getDisplayValue(),
						sys_id: positionGr.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Shuttle',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Shuttle');
				workerSkillGr.query();
				if (workerSkillGr.next()) {
					return this.MASTERIES.find(mstry => mstry.id == workerSkillGr.mastery.sys_id).label;
				} else {
					return this.UNQUALIFIED.label;
				}
			},
			getPositions: function() {
				// ===== TODO: Use position skills =====
				var positions = [];
				var positionGr = new GlideRecord('x_802331_eyva_position');
				positionGr.addQuery('work_performed', 'shuttle');
				positionGr.query();
				while (positionGr.next()) {
					positions.push({
						name: positionGr.name.getDisplayValue(),
						sys_id: positionGr.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Sitting',
			getMasteryByWorker: (worker) => {
				// All adults have this skill, unless they only have the shuttle skill			
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.query();
				if (workerSkillGr.next() && workerSkillGr.getRowCount() == 1) {
					if (workerSkillGr.skill.getDisplayValue() == "Shuttle") {
						return false;
					}
				}
				return worker.getValue('adult') == true ? this.PROFICIENT.label : this.UNQUALIFIED.label;
			},
			getPositions: function() {
				// Find active positions, not normally for kids, with no skills required
				var positions = [];
				var positionGr = new GlideRecord('x_802331_eyva_position');
				positionGr.addQuery('normally_for_kids', false);
				positionGr.addActiveQuery();
				positionGr.query();
				while (positionGr.next()) {
					var positionSkillGa = new GlideAggregate('x_802331_eyva_position_skill');
					positionSkillGa.addQuery('position', positionGr.sys_id);
					positionSkillGa.addAggregate('COUNT');
					positionSkillGa.query();
					positionSkillGa.next();
					if (positionSkillGa.getAggregate('COUNT') <= 0) {
						positions.push({
							name: positionGr.name.getDisplayValue(),
							sys_id: positionGr.sys_id.toString()
						});
					}
				}
				return positions;
			}
		},
		{
			name: 'Standing',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addEncodedQuery('skill.name=Basic Adult^ORskill.name=Basic Kid');
				workerSkillGr.query();
				return workerSkillGr.getRowCount() >= 1 && this.PROFICIENT.label || this.UNQUALIFIED.label;
			},
			getPositions: function() {
				// Find active positions that require either 'Basic Adult' or 'Basic Kid'
				var positions = [];
				var positionSkillGa = new GlideAggregate('x_802331_eyva_position_skill');
				positionSkillGa.addQuery('position.active', true);
				positionSkillGa.addEncodedQuery('skill.name=Basic Adult^ORskill.name=Basic Kid');
				positionSkillGa.groupBy('position');
				positionSkillGa.query();
				while (positionSkillGa.next()) {
					positions.push({
						name: positionSkillGa.position.name.getDisplayValue(),
						sys_id: positionSkillGa.position.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Basic Point',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Basic Point');
				workerSkillGr.query();
				return workerSkillGr.getRowCount() >= 1 && this.PROFICIENT.label || this.UNQUALIFIED.label;
			},
			getPositions: function() {
				// Find active positions that require 'Basic Point'
				var positions = [];
				var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
				positionSkillGr.addQuery('position.active', true);
				positionSkillGr.addQuery('skill.name', 'Basic Point');
				positionSkillGr.query();
				while (positionSkillGr.next()) {
					positions.push({
						name: positionSkillGr.position.name.getDisplayValue(),
						sys_id: positionSkillGr.position.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Point Alpha',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Point Alpha');
				workerSkillGr.query();
				if (workerSkillGr.next()) {
					return this.MASTERIES.find(mstry => mstry.id == workerSkillGr.mastery.sys_id).label;
				} else {
					return this.UNQUALIFIED.label;
				}
			},
			getPositions: function() {
				// Find active positions that require 'Point Alpha'
				var positions = [];
				var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
				positionSkillGr.addQuery('position.active', true);
				positionSkillGr.addQuery('skill.name', 'Point Alpha');
				positionSkillGr.query();
				while (positionSkillGr.next()) {
					positions.push({
						name: positionSkillGr.position.name.getDisplayValue(),
						sys_id: positionSkillGr.position.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Point Bravo',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Point Bravo');
				workerSkillGr.query();
				if (workerSkillGr.next()) {
					return this.MASTERIES.find(mstry => mstry.id == workerSkillGr.mastery.sys_id).label;
				} else {
					return this.UNQUALIFIED.label;
				}
			},
			getPositions: function() {
				// Find active positions that require 'Point Bravo'
				var positions = [];
				var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
				positionSkillGr.addQuery('position.active', true);
				positionSkillGr.addQuery('skill.name', 'Point Bravo');
				positionSkillGr.query();
				while (positionSkillGr.next()) {
					positions.push({
						name: positionSkillGr.position.name.getDisplayValue(),
						sys_id: positionSkillGr.position.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Drink Cart',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Drink Cart');
				workerSkillGr.query();
				if (workerSkillGr.next()) {
					return this.MASTERIES.find(mstry => mstry.id == workerSkillGr.mastery.sys_id).label;
				} else {
					return this.UNQUALIFIED.label;
				}
			},
			getPositions: function() {
				// Find active positions that require 'Drink Cart'
				var positions = [];
				var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
				positionSkillGr.addQuery('position.active', true);
				positionSkillGr.addQuery('skill.name', 'Drink Cart');
				positionSkillGr.query();
				while (positionSkillGr.next()) {
					positions.push({
						name: positionSkillGr.position.name.getDisplayValue(),
						sys_id: positionSkillGr.position.sys_id.toString()
					});
				}
				return positions;
			}
		},
		{
			name: 'Zone Supervisor',
			getMasteryByWorker: (worker) => {
				var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
				workerSkillGr.addQuery('worker', worker.sys_id);
				workerSkillGr.addQuery('skill.name', 'Zone Supervisor');
				workerSkillGr.query();
				if (workerSkillGr.next()) {
					return this.MASTERIES.find(mstry => mstry.id == workerSkillGr.mastery.sys_id).label;
				} else {
					return this.UNQUALIFIED.label;
				}
			},
			getPositions: function() {
				// Find active positions that require 'Zone Supervisor'
				var positions = [];
				var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
				positionSkillGr.addQuery('position.active', true);
				positionSkillGr.addQuery('skill.name', 'Zone Supervisor');
				positionSkillGr.query();
				while (positionSkillGr.next()) {
					positions.push({
						name: positionSkillGr.position.name.getDisplayValue(),
						sys_id: positionSkillGr.position.sys_id.toString()
					});
				}
				return positions;
			}
		}];
    },

	/**
	  * Determine if a user is qualified for the given position.
	  *
	  * @params
	  *     worker       : GlideRecord of worker
	  *     position     : GlideRecord of position
	  *
	  * @returns
	  *     string indicating level of proficiency (empty string if not qualified at all)
	  */
	isWorkerQualifiedForPosition: function(worker, position) {
		// Get skills of the worker
		var workerSkillGr = new GlideRecord('x_802331_eyva_worker_skill');
		workerSkillGr.addQuery('worker', worker.sys_id);
		workerSkillGr.query();

		var workerSkills = {};
		while (workerSkillGr.next()) {
			var skillId = workerSkillGr.getValue('skill');
			workerSkills[skillId] = workerSkillGr.getValue('mastery');
		}

		// Check for shuttle-only worker
		var shuttleSkillId = 'a4043eff477fa1102dabcd9bd36d43be';
		if (workerSkillGr.getRowCount() == 1 && workerSkills[shuttleSkillId]) {
			if (position.getValue('work_performed') != "shuttle") {
				return this.UNQUALIFIED.label;
			}
		}

		// Get required skills for the position
		var positionSkillGr = new GlideRecord('x_802331_eyva_position_skill');
		positionSkillGr.addQuery('position', position.sys_id);
		positionSkillGr.query();

		// No skills required
		if (positionSkillGr.getRowCount() <= 0) {
			if (position.getValue('normally_for_kids') != worker.getValue('adult')) {
				// (Position is normally for kids + kid worker) OR (Position is normally for adults + adult worker)
				return this.PROFICIENT.label;
			} else {
				return this.UNQUALIFIED.label;
			}
		}

		// One or more skills required
		while (positionSkillGr.next()) {
			var skillId = positionSkillGr.getValue('skill');

			// If worker has at least one required skill
			if (workerSkills[skillId] == this.PROFICIENT.id) {
				return this.PROFICIENT.label;
			} // If worker needs help with a skill
			else if (workerSkills[skillId] == this.NEEDSTRAINING.id || workerSkills[skillId] == this.NEEDSHELP.id) {
				return this.NEEDSHELP.label;
			}
		}

		// If made it here, worker doesn't have any required skill
		return this.UNQUALIFIED.label;
	},

	getNextOrder: function(table, filter, groupByField, orderField) {
		var ga = new GlideAggregate(table);
		ga.addEncodedQuery(filter);
		ga.addAggregate('MAX', orderField);
		ga.groupBy(groupByField);
		ga.orderByDesc(orderField);
		ga.query();
		if (ga.next()) {
			return parseInt(ga.getAggregate('MAX', orderField) || 0) + 1;
		} else {
			return 1;
		}
	},

	setPreviousShiftPosition: function(shiftWorker) {

	},

	getPreviousShiftPosition: function(shiftWorker) {

	},

	isInSamePositionAsPreviousShift: function(shiftPositionWorker) {
		var prevShiftPos = '';//Search "api.data.look_up_shift_position_workers" for same worker in previous shift
			//this.getPreviousShiftPosition(shiftPositionWorker.shift_worker.value);
		var currShiftPos = '';//Search "api.data.look_up_shift_position_workers" for same worker in previous shift
			//new GlideRecord('x_802331_eyva_shift_position');
		return prevShiftPos._reference.position.value == currShiftPos._reference.position.value;
	},

	isInSameAreaAsPreviousShift: function(shiftPositionWorker) {
		var prevShiftPos = '';//Search "api.data.look_up_shift_position_workers" for same worker in previous shift
		var currShiftPos = '';//Search "api.data.look_up_shift_position_workers" for same worker in previous shift
		return prevShiftPos._reference.position._reference.area.value == currShiftPos._reference.position._reference.area.value;

		// Points

		// Green / Orange

		// Point E / Point G / Green

		// Point D / Orange / Media

		// Diamond / 15-Minute / Point A / Point B / Point C

		// Shuttles
	},

	/**
	  * Get a worker's skills.
	  *
	  * @params
	  *     worker       : GlideRecord of worker
	  *
	  * @returns
	  *     array of skills (as expected by front-end)
	  */
	getWorkerSkills: function(worker) {
		var skills = {};
		this.SKILLS.forEach(function(skl) {
			skills[skl.name.toLowerCase().replaceAll(' ', '_')] = {
				name: skl.name,
				mastery: skl.getMasteryByWorker(worker)
			};
		});
		return skills;
	},

    type: 'EyvaUtils'
};
